// The game-systems parity audit: trading, brewing, enchanting, effects, smithing, commands and redstone, each fact
// from the Minecraft Wiki (Java Edition; src/systemsWikiData.js, generated by scripts/generate-systems-wiki-data.mjs)
// asked of the code the game runs. Verdicts PASS / FAIL / NA (the wiki names something this game does not have --
// post-1.21.4 content, listed in docs/missing-content.md). No DOM or Three.js, so the tests, the CLI
// (scripts/wiki-audit.mjs --systems) and the Resource Inspector share it.
import { PROFESSION_TRADES, WIKI_ID_ALIASES, resolveWikiId } from './villagerEconomy.js';
import { TRADES as WANDERING_TRADES } from './wanderingTraderBehavior.js';
import { cellForName, cellLabel, normName } from './wikiNames.js';
import { WIKI_TRADES, WIKI_BREWING, WIKI_ENCHANTMENTS, WIKI_TABLE_OFFERS, WIKI_EFFECTS, WIKI_SMITHING, WIKI_COMMANDS, WIKI_REDSTONE } from './systemsWikiData.js';
import { Redstone } from './redstone.js';
import { findCommand } from './commands.js';
import { calculateSmithingResult, NETHERITE_UPGRADE_TEMPLATE, TRIM_PATTERNS, TRIM_TEMPLATES, TRIM_MATERIALS, trimOf } from './smithing.js';
import { EFFECTS } from './statusEffects.js';
import { ENCHANTMENT_REGISTRY, incompatibleWith, eligibleEnchantments, anvilAccepts } from './enchanting.js';
import { getBrewingResult, POTION_DATA, BREW_DURATION, MAX_FUEL } from './brewing.js';

const WIKI = 'https://minecraft.wiki/w/';

/** What each case id checks, for the Inspector's audit summary and the CLI. */
export const SYSTEMS_CASE_LABELS = {
  'T-TRADE': 'Villager / wandering trader trade',
  'B-BREW': 'Brewing recipe', 'B-DURATION': 'Potion duration', 'B-FORM': 'Extended / enhanced / splash / lingering form', 'B-STAND': 'Brewing stand',
  'E-MAX': 'Enchantment max level', 'E-CONFLICT': 'Enchantment conflicts', 'E-ANVIL': 'Enchantment items (anvil)', 'E-WEIGHT': 'Enchantment weight',
  'E-COST': 'Enchantment cost ranges', 'E-ITEMS': 'Enchanting table offers',
  'X-EFFECT': 'Status effect exists', 'X-NAME': 'Effect name', 'X-TYPE': 'Effect type', 'X-POTENCY': 'Effect scales with level',
  'M-UPGRADE': 'Netherite upgrade', 'M-TEMPLATE': 'Armor trim template', 'M-MATERIAL': 'Trim material', 'M-TRIM': 'Armor trimming',
  'K-COMMAND': 'Java command', 'K-LEVEL': 'Command permission level',
  'R-DUST': 'Redstone dust', 'R-REPEATER': 'Repeater', 'R-COMPARATOR': 'Comparator', 'R-TORCH': 'Redstone torch', 'R-PISTON': 'Piston',
  'R-OBSERVER': 'Observer', 'R-BUTTON': 'Button', 'R-PLATE': 'Pressure plate', 'R-DROPPER': 'Dropper / dispenser', 'R-HOPPER': 'Hopper',
  'R-NOTE': 'Note block', 'R-TARGET': 'Target', 'R-ROD': 'Lightning rod', 'R-CONTAINER': 'Comparator reading a container',
};
export function verdict(system, id, subject, label, expected, actual, ok, { source = null, note = null } = {}) {
  return { system, id, subject, label, status: ok === null ? 'NA' : ok ? 'PASS' : 'FAIL', expected: String(expected), actual: String(actual), source, note };
}
import { BLOCKS } from './blocks.js';

/**
 * The keys a trade side answers to: its display name and its id, normalised (a game side), or the wiki's name and
 * the display name of what that name resolves to (a wiki side). Two sides are the same item when the sets meet.
 */
function gameKeys(id, isBlock, extra = []) {
  const plain = typeof id === 'number' ? id : resolveWikiId(id);
  const cell = typeof plain === 'number' ? { id: plain, isBlock: true }
    : isBlock !== undefined ? { id: plain, isBlock } : (cellForName(plain) ?? (typeof BLOCKS[String(plain).toUpperCase()] === 'number' ? { id: BLOCKS[String(plain).toUpperCase()], isBlock: true } : { id: plain, isBlock: false }));
  return new Set([normName(cellLabel(cell)), normName(id), normName(String(plain).replace(/_block$/, '')), ...extra.filter(Boolean).map(normName)]);
}
/** A wiki name's keys. "Enchanted Iron Axe" is an iron axe the trade enchants; "Any color Wool" any colour of wool. */
function wikiKeys(name) {
  const plain = name.replace(/^Enchanted (?!Book|Golden Apple)/, '').replace(/^Any colou?r /, '');
  // A wiki name the trade tables register under another id ("Boat" is the oak boat, an explorer map a named filled map).
  const alias = WIKI_ID_ALIASES[plain.toLowerCase().replace(/[^a-z0-9]+/g, '_')];
  const cell = cellForName(plain) ?? (typeof alias === 'string' ? cellForName(alias) : null);
  const keys = new Set([normName(plain), ...(cell ? [normName(cellLabel(cell))] : []), ...(typeof alias === 'string' ? [normName(alias)] : [])]);
  return { keys, anyColour: /^Any colou?r /.test(name), plain, known: Boolean(cell) || Boolean(alias) || /^Any colou?r /.test(name) };
}
const meets = (a, b) => [...a].some((k) => b.has(k));
const COLOURS = ['white', 'orange', 'magenta', 'lightblue', 'yellow', 'lime', 'pink', 'gray', 'lightgray', 'cyan', 'purple', 'blue', 'brown', 'green', 'red', 'black'];
/** Does a game side match a wiki side, an "any colour" one matching any colour of the item? */
function sideMatches(game, wiki) {
  if (meets(game, wiki.keys)) return true;
  if (!wiki.anyColour) return false;
  // "Stained Terracotta" is the coloured terracotta, "White Terracotta" in its own name.
  const bases = [normName(wiki.plain), normName(wiki.plain.replace(/^Stained /, ''))];
  return [...game].some((k) => COLOURS.some((c) => bases.some((b) => k === c + b)));
}
const range = (min, max) => (min === max ? `${min}` : `${min}-${max}`);

// --- trading ------------------------------------------------------------------------------------------------------

/** The game's offers as comparable rows. */
function gameTradeRows() {
  const rows = [];
  for (const [profession, list] of Object.entries(PROFESSION_TRADES)) {
    for (const r of list) {
      const side = (s) => (s ? { keys: gameKeys(s.id, s.isBlock, [s.wikiId, s.name]), min: s.countMin ?? s.count, max: s.countMax ?? s.count } : null);
      rows.push({ trader: profession, level: r.level, wants: [side(r.cost), side(r.cost2)].filter(Boolean), gives: side(r.reward), stock: r.maxUses, xp: r.xp, multiplier: r.priceMultiplier, raw: r });
    }
  }
  for (const [group, list] of Object.entries(WANDERING_TRADES)) {
    for (const r of list) {
      rows.push({ trader: 'wandering_trader', group, wants: [{ keys: gameKeys(r.want), min: r.wantCount, max: r.wantCountMax ?? r.wantCount }],
        gives: { keys: gameKeys(r.give), min: r.giveCount, max: r.giveCount }, stock: r.maxTrades, raw: r });
    }
  }
  return rows;
}

const tradeLabel = (t) => `${t.trader}${t.level ? ` L${t.level}` : ''}: ${t.wants.map((w) => `${range(w.min, w.max)} ${w.name}`).join(' + ')} -> ${range(t.gives.min, t.gives.max)} ${t.gives.name}`;

/** Every wiki trade, found among the game's offers by trader, level and items, and its numbers compared. */
export function tradeCases() {
  const game = gameTradeRows();
  return WIKI_TRADES.map((t) => {
    const label = tradeLabel(t);
    const unknown = [...t.wants, t.gives].filter((s) => !wikiKeys(s.name).known).map((s) => s.name);
    if (unknown.length) return verdict('trading', 'T-TRADE', t.trader, label, 'offered', '—', null, { source: `${WIKI}Trading`, note: `not in this game: ${unknown.join(', ')}` });
    const want = t.wants.map((w) => wikiKeys(w.name)); const give = wikiKeys(t.gives.name);
    const candidates = game.filter((g) => g.trader === t.trader && (t.level === undefined || g.level === t.level) && g.gives && sideMatches(g.gives.keys, give)
      && g.wants.length === want.length && g.wants.every((w, i) => sideMatches(w.keys, want[i])));
    if (!candidates.length) return verdict('trading', 'T-TRADE', t.trader, label, 'offered', 'no such offer', false, { source: `${WIKI}Trading` });
    const facts = (x) => ({ wants: x.wants.map((w) => range(w.min, w.max)).join('+'), gives: range(x.gives.min, x.gives.max), stock: x.stock, ...(x.xp !== undefined ? { xp: x.xp, multiplier: x.multiplier } : {}) });
    const expected = facts(t);
    const best = candidates.find((g) => JSON.stringify(facts(g)) === JSON.stringify(expected)) ?? candidates[0];
    const actual = facts(best);
    return verdict('trading', 'T-TRADE', t.trader, label, JSON.stringify(expected), JSON.stringify(actual), JSON.stringify(actual) === JSON.stringify(expected), { source: `${WIKI}Trading` });
  });
}

// --- brewing ------------------------------------------------------------------------------------------------------

const seconds = (mmss) => (mmss ? mmss.split(':').reduce((m, s) => Number(m) * 60 + Number(s)) : null);
const potionId = (name) => cellForName(name)?.id ?? name.toLowerCase().replace(/[^a-z0-9]+/g, '_');

/**
 * The Brewing page's recipe tables asked of getBrewingResult: every ingredient on every base it lists makes the
 * potion; the potion lasts the wiki's time; its extended (redstone) and enhanced (glowstone) forms exist exactly
 * when the wiki gives them, and last their times.
 */
export function brewingCases() {
  const out = [];
  const src = `${WIKI}Brewing`;
  for (const p of WIKI_BREWING) {
    const id = potionId(p.potion);
    for (const r of p.recipes) {
      for (const ingName of r.ingredients) {
        const ing = cellForName(ingName);
        for (const base of r.bases) {
          const made = ing ? getBrewingResult(potionId(base), ing.id) : null;
          out.push(verdict('brewing', 'B-BREW', p.potion, `${base} + ${ingName} -> ${p.potion}`, id, made ?? 'nothing', ing ? made === id : null,
            { source: src, note: ing ? null : `not in this game: ${ingName}` }));
        }
      }
    }
    const data = POTION_DATA[id];
    if (p.duration) out.push(verdict('brewing', 'B-DURATION', p.potion, `${p.potion} lasts ${p.duration}`, seconds(p.duration), data?.duration ?? 'none', data?.duration === seconds(p.duration), { source: src }));
    for (const [form, ingredient, suffix] of [['extended', 'redstone', '_long'], ['enhanced', 'glowstone_dust', '_2']]) {
      if (!('extended' in p)) continue; // a base potion's row has no such columns
      const made = getBrewingResult(id, ingredient);
      const wiki = p[form];
      if (!wiki) {
        out.push(verdict('brewing', 'B-FORM', p.potion, `${p.potion} has no ${form} form`, 'nothing', made ?? 'nothing', made === null || made === undefined, { source: src }));
        continue;
      }
      out.push(verdict('brewing', 'B-FORM', p.potion, `${p.potion} + ${ingredient} -> ${form}`, id + suffix, made ?? 'nothing', made === id + suffix, { source: src }));
      if (wiki.duration) {
        const d = POTION_DATA[id + suffix]?.duration;
        out.push(verdict('brewing', 'B-DURATION', p.potion, `${form} ${p.potion} lasts ${wiki.duration}`, seconds(wiki.duration), d ?? 'none', d === seconds(wiki.duration), { source: src }));
      }
    }
  }
  // The Brewing page's equipment and form rules: "Each brewing operation takes 20 seconds"; blaze powder "Holds 20
  // charges"; gunpowder makes a splash potion and dragon's breath a lingering one of a splash potion.
  out.push(verdict('brewing', 'B-STAND', 'brewing_stand', 'A brew takes 20 seconds', 20, BREW_DURATION, BREW_DURATION === 20, { source: src }));
  out.push(verdict('brewing', 'B-STAND', 'blaze_powder', 'Blaze powder holds 20 charges', 20, MAX_FUEL, MAX_FUEL === 20, { source: src }));
  out.push(verdict('brewing', 'B-FORM', 'splash', 'Potion + Gunpowder -> Splash Potion', 'splash_potion_of_healing', getBrewingResult('potion_of_healing', 'gunpowder'), getBrewingResult('potion_of_healing', 'gunpowder') === 'splash_potion_of_healing', { source: src }));
  out.push(verdict('brewing', 'B-FORM', 'lingering', "Splash Potion + Dragon's Breath -> Lingering Potion", 'lingering_potion_of_healing', getBrewingResult('splash_potion_of_healing', 'dragon_breath'), getBrewingResult('splash_potion_of_healing', 'dragon_breath') === 'lingering_potion_of_healing', { source: src }));
  return out;
}

// --- enchanting ---------------------------------------------------------------------------------------------------

// Content newer than the Java release this game targets (1.21.4; see docs/missing-content.md): the spear and its
// Lunge enchantment. Their rows are NA, not FAIL.
const LATER_THAN_TARGET = { lunge: 'Lunge (spears, Java 1.21.11)', Spear: 'spears (Java 1.21.11)' };
// The wiki's item groups, as the game item each is asked with. "Pickaxe/Shovel/Hoe" share one row.
const ITEM_FOR_GROUP = {
  Helmet: 'iron_helmet', 'Turtle Shell': 'turtle_helmet', Chestplate: 'iron_chestplate', Leggings: 'iron_leggings', Boots: 'iron_boots',
  Sword: 'iron_sword', Axe: 'iron_axe', Pickaxe: 'iron_pickaxe', Shovel: 'iron_shovel', Hoe: 'iron_hoe', Bow: 'bow', Crossbow: 'crossbow',
  'Fishing Rod': 'fishing_rod', Trident: 'trident', Mace: 'mace', Book: 'book', Spear: 'iron_spear',
};
const enchantmentKey = (name) => WIKI_ENCHANTMENTS.find((e) => e.name === name)?.id ?? name.toLowerCase().replace(/[^a-z0-9]+/g, '_');

/**
 * The Enchantment page's list (maximum level, what each cannot share an item with) and the Enchanting table
 * mechanics page's offers (which enchantments the table offers each item; each one's weight and cost ranges),
 * asked of ENCHANTMENT_REGISTRY, incompatibleWith and eligibleEnchantments.
 */
export function enchantingCases() {
  const out = [];
  const listSrc = `${WIKI}Enchantment`; const tableSrc = `${WIKI}Enchanting_table_mechanics`;
  for (const e of WIKI_ENCHANTMENTS) {
    const def = ENCHANTMENT_REGISTRY[e.id];
    if (LATER_THAN_TARGET[e.id]) { out.push(verdict('enchanting', 'E-MAX', e.id, `${e.name} max level`, e.maxLevel, def?.maxLevel ?? '—', null, { source: listSrc, note: `newer than this game's target: ${LATER_THAN_TARGET[e.id]}` })); continue; }
    out.push(verdict('enchanting', 'E-MAX', e.id, `${e.name} max level`, e.maxLevel, def?.maxLevel ?? 'not in the game', def?.maxLevel === e.maxLevel, { source: listSrc }));
    const wiki = e.incompatible.map(enchantmentKey).filter((k) => !LATER_THAN_TARGET[k]).sort();
    const game = def ? incompatibleWith(e.id).sort() : [];
    out.push(verdict('enchanting', 'E-CONFLICT', e.id, `${e.name} cannot share an item with`, wiki.join(', ') || 'nothing', def ? game.join(', ') || 'nothing' : 'not in the game', def && wiki.join() === game.join(), { source: listSrc }));
  }
  // The anvil: every item the page lists for an enchantment, primary or secondary, takes it; no other item does.
  const ANVIL_ITEMS = { ...ITEM_FOR_GROUP, Shears: 'shears', 'Flint and Steel': 'flint_and_steel', Shield: 'shield', Elytra: 'elytra',
    'Carrot on a Stick': 'carrot_on_a_stick', 'Warped Fungus on a Stick': 'warped_fungus_on_a_stick', Brush: 'brush' };
  delete ANVIL_ITEMS.Book; delete ANVIL_ITEMS.Spear;
  for (const e of WIKI_ENCHANTMENTS) {
    const def = ENCHANTMENT_REGISTRY[e.id];
    if (LATER_THAN_TARGET[e.id] || !def) continue;
    const listed = new Set([...e.primary, ...e.secondary]);
    // The curses are on any item with durability, which the page writes as prose rather than as icons.
    if (/curse/.test(e.id)) continue;
    const wrong = Object.entries(ANVIL_ITEMS).filter(([group, item]) => listed.has(group) !== anvilAccepts(def, item))
      .map(([group]) => `${group} ${listed.has(group) ? 'refused' : 'accepted'}`);
    out.push(verdict('enchanting', 'E-ANVIL', e.id, `An anvil puts ${e.name} on exactly its items`, [...listed].filter((g) => ANVIL_ITEMS[g]).join(', '), wrong.length ? wrong.join('; ') : 'as listed', wrong.length === 0, { source: listSrc }));
  }
  const groups = new Map();
  for (const o of WIKI_TABLE_OFFERS) {
    const key = enchantmentKey(o.name);
    for (const group of o.items) { if (!groups.has(group)) groups.set(group, new Set()); groups.get(group).add(key); }
    if (o.items.includes('Book')) {
      const def = ENCHANTMENT_REGISTRY[key];
      if (LATER_THAN_TARGET[key]) continue;
      out.push(verdict('enchanting', 'E-WEIGHT', key, `${o.name} weight`, o.weight, def?.weight ?? 'not in the game', def?.weight === o.weight, { source: tableSrc }));
      const game = def?.cost?.slice(0, o.costs.length).map((r) => r.join('–')).join(', ');
      out.push(verdict('enchanting', 'E-COST', key, `${o.name} cost ranges`, o.costs.map((r) => r.join('–')).join(', '), game ?? 'not in the game', game === o.costs.map((r) => r.join('–')).join(', '), { source: tableSrc }));
    }
  }
  for (const [group, wikiSet] of groups) {
    const item = ITEM_FOR_GROUP[group];
    if (LATER_THAN_TARGET[group]) { out.push(verdict('enchanting', 'E-ITEMS', group, `The table offers a ${group}`, [...wikiSet].sort().join(', '), '—', null, { source: tableSrc, note: `newer than this game's target: ${LATER_THAN_TARGET[group]}` })); continue; }
    const wiki = [...wikiSet].filter((k) => !LATER_THAN_TARGET[k]).sort();
    const game = eligibleEnchantments(item).map((c) => c.key).sort();
    out.push(verdict('enchanting', 'E-ITEMS', group, `The table offers a ${group} (${item})`, wiki.join(', '), game.join(', ') || 'nothing', wiki.join() === game.join(), { source: tableSrc }));
  }
  return out;
}

// --- effects ------------------------------------------------------------------------------------------------------

// Effects newer than the target release: Breath of the Nautilus came with the nautilus (Java 1.21.11).
const EFFECT_LATER_THAN_TARGET = { breath_of_the_nautilus: 'Java 1.21.11 (nautilus)' };
const CATEGORY_FOR_TYPE = { Positive: 'beneficial', Negative: 'harmful', Neutral: 'neutral' };

/** The Effect page's list asked of statusEffects.js: every Java effect exists, with its name, its type and whether its level matters. */
export function effectCases() {
  const out = [];
  const src = `${WIKI}Effect`;
  for (const e of WIKI_EFFECTS) {
    const def = EFFECTS[e.id];
    const skip = /Bedrock/.test(e.only ?? '') ? 'Bedrock Edition only' : /upcoming/.test(e.only ?? '') ? 'an upcoming version' : EFFECT_LATER_THAN_TARGET[e.id];
    if (skip) { out.push(verdict('effects', 'X-EFFECT', e.id, `${e.name} exists`, 'an effect', def ? 'present' : '—', null, { source: src, note: `not this game's target: ${skip}` })); continue; }
    out.push(verdict('effects', 'X-EFFECT', e.id, `${e.name} exists`, 'an effect', def ? 'present' : 'missing', Boolean(def), { source: src }));
    if (!def) continue;
    out.push(verdict('effects', 'X-NAME', e.id, `${e.id} is called ${e.name}`, e.name, def.name, def.name === e.name, { source: src }));
    out.push(verdict('effects', 'X-TYPE', e.id, `${e.name} is ${e.type}`, CATEGORY_FOR_TYPE[e.type], def.category, def.category === CATEGORY_FOR_TYPE[e.type], { source: src }));
    if (e.scalesWithPotency !== undefined && def.scalesWithPotency !== undefined) {
      out.push(verdict('effects', 'X-POTENCY', e.id, `${e.name} ${e.scalesWithPotency ? 'scales' : 'does not scale'} with its level`, e.scalesWithPotency, def.scalesWithPotency, def.scalesWithPotency === e.scalesWithPotency, { source: src }));
    }
  }
  return out;
}

// --- smithing -----------------------------------------------------------------------------------------------------

// Items on the Smithing page newer than the target release: netherite horse armour, nautilus armour and spears
// (Java 1.21.11), copper armour (Java 1.21.9).
const SMITHING_LATER_THAN_TARGET = /Horse Armor|Nautilus Armor|Spear|^Copper (Helmet|Chestplate|Leggings|Boots)$/;
const itemIdOf = (name) => cellForName(name)?.id ?? null;

/** The Smithing page asked of calculateSmithingResult: every upgrade, every template and material, every trim example. */
export function smithingCases() {
  const out = [];
  const src = `${WIKI}Smithing`;
  const later = (...names) => names.find((n) => SMITHING_LATER_THAN_TARGET.test(n));
  for (const u of WIKI_SMITHING.upgrades) {
    const label = `${u.template} + ${u.base} + ${u.addition} -> ${u.result}`;
    if (later(u.base, u.result)) { out.push(verdict('smithing', 'M-UPGRADE', u.result, label, itemIdOf(u.result) ?? u.result, '—', null, { source: src, note: `newer than this game's target: ${later(u.base, u.result)}` })); continue; }
    const made = calculateSmithingResult({ id: NETHERITE_UPGRADE_TEMPLATE }, { id: itemIdOf(u.base) }, { id: itemIdOf(u.addition) });
    out.push(verdict('smithing', 'M-UPGRADE', u.result, label, itemIdOf(u.result), made.result?.id ?? `nothing (${made.reason})`, made.valid && made.result?.id === itemIdOf(u.result), { source: src }));
  }
  for (const t of WIKI_SMITHING.templates) {
    const id = `${t.replace(/ Armor Trim$/, '').toLowerCase()}_armor_trim_smithing_template`;
    out.push(verdict('smithing', 'M-TEMPLATE', id, `${t} Smithing Template trims armour`, id, TRIM_PATTERNS[id] ? id : 'missing', Boolean(TRIM_PATTERNS[id]), { source: src }));
  }
  for (const m of WIKI_SMITHING.materials) {
    const id = itemIdOf(m);
    out.push(verdict('smithing', 'M-MATERIAL', id ?? m, `${m} is a trim material`, id, TRIM_MATERIALS[id] ? id : 'not a material', Boolean(TRIM_MATERIALS[id]), { source: src }));
  }
  for (const [i, ex] of WIKI_SMITHING.trimExamples.entries()) {
    const label = `Any trim template + ${ex.base} + ${ex.material}`;
    if (later(ex.base)) { out.push(verdict('smithing', 'M-TRIM', ex.base, label, 'trimmed', '—', null, { source: src, note: `newer than this game's target: ${ex.base}` })); continue; }
    const template = TRIM_TEMPLATES[i % TRIM_TEMPLATES.length];
    const made = calculateSmithingResult({ id: template }, { id: itemIdOf(ex.base) }, { id: itemIdOf(ex.material) });
    const trim = made.result ? trimOf(made.result) : null;
    out.push(verdict('smithing', 'M-TRIM', ex.base, label, `${itemIdOf(ex.base)} with a ${TRIM_PATTERNS[template]} trim of ${itemIdOf(ex.material)}`,
      made.valid ? `${made.result.id} with ${JSON.stringify(trim)}` : `nothing (${made.reason})`, made.valid && made.result.id === itemIdOf(ex.base) && Boolean(trim), { source: src }));
  }
  return out;
}

// --- commands -----------------------------------------------------------------------------------------------------

/** "1.21.6" newer than 1.21.4? The year versions ("26.1") are all newer. Alpha/classic labels are old. */
export function newerThanTarget(version, target = [1, 21, 4]) {
  const m = /^(\d+)\.(\d+)(?:\.(\d+))?$/.exec(String(version ?? ''));
  if (!m) return false;
  const v = [Number(m[1]), Number(m[2]), Number(m[3] ?? 0)];
  for (let i = 0; i < 3; i++) if (v[i] !== target[i]) return v[i] > target[i];
  return false;
}

/**
 * Java commands this game does not run, because the system they drive is not in the game. Each says which. They
 * are reported as KNOWN, not PASS: a known gap with its reason, listed in docs/block-item-audit-plan.md.
 */
export const COMMANDS_WITHOUT_A_SYSTEM = Object.freeze({
  // Empty since round 4: advancedCommands.js gave each of the 31 its system.
});

/** The Commands page's Java list asked of the command table (commands.js) the chat dispatches from. */
export function commandCases() {
  const out = [];
  const src = `${WIKI}Commands`;
  for (const c of WIKI_COMMANDS) {
    const label = `/${c.name}`;
    const have = findCommand(c.name);
    if (c.multiplayerOnly || c.singleplayerOnly) { out.push(verdict('commands', 'K-COMMAND', c.name, label, 'a command', have ? 'present' : '—', null, { source: src, note: c.multiplayerOnly ? 'multiplayer (server) only' : 'opens a single-player world to LAN' })); continue; }
    if (newerThanTarget(c.added)) { out.push(verdict('commands', 'K-COMMAND', c.name, label, 'a command', have ? 'present' : '—', null, { source: src, note: `added in Java ${c.added}, after this game's target` })); continue; }
    if (!have && COMMANDS_WITHOUT_A_SYSTEM[c.name]) { out.push({ ...verdict('commands', 'K-COMMAND', c.name, label, 'a command', 'not run', false, { source: src, note: `not run: ${COMMANDS_WITHOUT_A_SYSTEM[c.name]}` }), status: 'KNOWN' }); continue; }
    out.push(verdict('commands', 'K-COMMAND', c.name, label, 'a command', have ? `/${have.name}` : 'missing', Boolean(have), { source: src }));
    // A cheat in Java (OP level 2 or more) is gated here; a level-0 command is open to everyone.
    if (have && Number.isFinite(c.level)) {
      const gated = have.gate === true;
      out.push(verdict('commands', 'K-LEVEL', c.name, `/${c.name} needs OP level ${c.level}`, c.level > 0 ? 'a cheat' : 'open to everyone', gated ? 'a cheat' : 'open to everyone',
        (c.level > 0) === gated || ENGINE_UNGATED.has(c.name), { source: src, note: ENGINE_UNGATED.has(c.name) ? 'kept open here on purpose (see commands.js)' : null }));
    }
  }
  return out;
}
// Level-2 Java commands this game deliberately leaves open (commands.js explains each): /help is level 0 anyway.
const ENGINE_UNGATED = new Set([]);

// --- redstone -----------------------------------------------------------------------------------------------------

/** A redstone engine on an empty test world, with a stone floor at y = 0. The engine ticks per redstone tick. */
function redstoneBench() {
  const voxels = new Map();
  const at = (x, y, z) => `${x},${y},${z}`;
  const world = {
    getVoxel: (x, y, z) => voxels.get(at(x, y, z)) ?? (y === 0 ? BLOCKS.STONE : BLOCKS.AIR),
    setVoxel: (x, y, z, id) => { voxels.set(at(x, y, z), id); rs.notify(x, y, z); },
    getChunk: () => ({}),
  };
  const rs = new Redstone(world);
  const put = (x, y, z, id, dir) => { world.setVoxel(x, y, z, id); if (dir !== undefined) rs.configure([x, y, z], dir); return rs.state([x, y, z]); };
  const tick = (n = 1, actors = []) => { for (let i = 0; i < n; i++) rs.tick(actors); };
  /** Redstone ticks until `test()` holds (or `limit`). */
  const until = (test, limit = 60, actors = []) => { for (let i = 1; i <= limit; i++) { rs.tick(actors); if (test()) return i; } return Infinity; };
  /** How many redstone ticks `test()` stays true for: the current tick if it already holds, and those that follow. */
  const lasting = (test, limit = 60, actors = []) => { let n = test() ? 1 : 0; for (let i = 0; i < limit; i++) { rs.tick(actors); if (test()) n++; else if (n) break; } return n; };
  /** How many of the following redstone ticks `test()` holds for (not counting the current one). */
  const holdsAfter = (test, limit = 60, actors = []) => { let n = 0; for (let i = 0; i < limit; i++) { rs.tick(actors); if (test()) n++; else break; } return n; };
  return { rs, world, put, tick, until, lasting, holdsAfter };
}
const GT = 2; // game ticks per redstone tick

/**
 * The redstone components' wiki numbers asked of the engine itself: small circuits are built on a test world and
 * run, so each verdict is what the game does, not what a constant says.
 */
export function redstoneCases() {
  const out = [];
  const fact = (key) => WIKI_REDSTONE[key];
  const add = (key, subject, label, expected, actual, extra = {}) => out.push(verdict('redstone', key, subject, label, expected, actual, String(expected) === String(actual),
    { source: `${WIKI}${fact(extra.fact)?.page.replace(/ /g, '_') ?? 'Redstone_circuits'}`, note: fact(extra.fact)?.quote ? `"${fact(extra.fact).quote}"` : null }));

  { // Dust carries a signal 15 blocks, one weaker per block.
    const b = redstoneBench(); const lever = b.put(0, 1, 0, BLOCKS.LEVER); lever.on = true;
    for (let x = 1; x <= 17; x++) b.put(x, 1, 0, BLOCKS.REDSTONE_WIRE);
    b.tick(20);
    const reach = [...Array(17).keys()].map((i) => b.rs.state([i + 1, 1, 0]).power || 0).filter((p) => p > 0).length;
    add('R-DUST', 'redstone_wire', 'Redstone dust carries a signal this many blocks', fact('dustRange').value, reach, { fact: 'dustRange' });
  }
  { // Repeater: placed at the lowest delay (2 game ticks), steps 1-4 redstone ticks, and delays by its setting.
    const b = redstoneBench(); const r = b.put(1, 1, 0, BLOCKS.REPEATER, 0);
    add('R-REPEATER', 'repeater', 'A placed repeater\'s delay (game ticks)', fact('repeaterInitialDelayGameTicks').value, r.delay * GT, { fact: 'repeaterInitialDelayGameTicks' });
    const seen = [r.delay]; for (let i = 0; i < 4; i++) { b.rs.interact([1, 1, 0]); seen.push(r.delay); }
    add('R-REPEATER', 'repeater', 'Using a repeater steps its delay through', [...fact('repeaterDelays').value, 1].join(','), seen.join(','), { fact: 'repeaterDelays' });
    for (const delay of fact('repeaterDelays').value) {
      const c = redstoneBench(); const lever = c.put(0, 1, 0, BLOCKS.LEVER); const rep = c.put(1, 1, 0, BLOCKS.REPEATER, 0); rep.delay = delay;
      c.tick(3); lever.on = true;
      const latency = c.until(() => rep.output === 15) - 1; // the lever's own output lands on the first tick
      add('R-REPEATER', 'repeater', `A ${delay}-tick repeater passes a signal after (game ticks)`, delay * GT, latency * GT, { fact: 'repeaterDelays' });
    }
  }
  { // Comparator: 2 game ticks; compare mode keeps the rear (15) over a weaker side (13); subtract gives 2.
    const build = (subtract) => {
      const b = redstoneBench(); const rear = b.put(-1, 1, 0, BLOCKS.LEVER);
      const cmp = b.put(0, 1, 0, BLOCKS.COMPARATOR, 0); cmp.subtract = subtract;
      const side = b.put(0, 1, 4, BLOCKS.LEVER); for (let z = 1; z <= 3; z++) b.put(0, 1, z, BLOCKS.REDSTONE_WIRE);
      side.on = true; b.tick(10); rear.on = true;
      return { b, cmp, latency: b.until(() => cmp.output > 0) - 1 };
    };
    const compare = build(false); const subtract = build(true);
    add('R-COMPARATOR', 'comparator', 'A comparator passes its rear signal after (game ticks)', fact('comparatorDelayGameTicks').value, compare.latency * GT, { fact: 'comparatorDelayGameTicks' });
    add('R-COMPARATOR', 'comparator', 'Compare mode: rear 15, side 13 -> 15', 15, compare.cmp.output, { fact: 'comparatorDelayGameTicks' });
    add('R-COMPARATOR', 'comparator', 'Subtract mode: rear 15, side 13 -> 2', 2, subtract.cmp.output, { fact: 'comparatorDelayGameTicks' });
  }
  { // Redstone torch: inverts after 2 game ticks; burns out after more than eight turn-offs in 60 game ticks.
    const b = redstoneBench(); b.put(0, 1, 0, BLOCKS.STONE); const torch = b.put(0, 2, 0, BLOCKS.REDSTONE_TORCH); const lever = b.put(1, 1, 0, BLOCKS.LEVER);
    b.tick(5); lever.on = true;
    add('R-TORCH', 'redstone_torch', 'A torch turns off after its block is powered (game ticks)', fact('torchDelayGameTicks').value, (b.until(() => torch.output === 0) - 1) * GT, { fact: 'torchDelayGameTicks' });
    const c = redstoneBench(); c.put(0, 1, 0, BLOCKS.STONE); const t2 = c.put(0, 2, 0, BLOCKS.REDSTONE_TORCH); const l2 = c.put(1, 1, 0, BLOCKS.LEVER);
    c.tick(5);
    for (let i = 0; i < 30; i++) { l2.on = !l2.on; c.tick(); }
    l2.on = false; c.tick(3);
    add('R-TORCH', 'redstone_torch', 'A torch flickered off 15 times in 60 game ticks has burnt out (stays off unpowered)', 'off', t2.output === 0 ? 'off' : 'on', { fact: 'torchBurnout' });
    c.tick(40);
    add('R-TORCH', 'redstone_torch', 'A burnt-out torch relights once the flicker is past', 'on', t2.output === 15 ? 'on' : 'off', { fact: 'torchBurnout' });
  }
  { // Piston: 12 blocks move, 13 do not.
    const push = (n) => {
      const b = redstoneBench(); const piston = b.put(0, 1, 0, BLOCKS.PISTON, 0);
      for (let x = 1; x <= n; x++) b.put(x, 1, 0, BLOCKS.COBBLESTONE);
      b.put(0, 1, 1, BLOCKS.LEVER).on = true; b.tick(4);
      return piston.extended ? 'extends' : 'stays';
    };
    add('R-PISTON', 'piston', `A piston pushes a row of ${fact('pistonPushLimit').value} blocks`, 'extends', push(fact('pistonPushLimit').value), { fact: 'pistonPushLimit' });
    add('R-PISTON', 'piston', `...but not ${fact('pistonPushLimit').value + 1}`, 'stays', push(fact('pistonPushLimit').value + 1), { fact: 'pistonPushLimit' });
  }
  { // Observer: a 2-game-tick pulse at 15 when the block it faces changes.
    const b = redstoneBench(); const obs = b.put(0, 1, 0, BLOCKS.OBSERVER, 0); b.tick(3);
    b.world.setVoxel(1, 1, 0, BLOCKS.COBBLESTONE);
    add('R-OBSERVER', 'observer', 'An observer\'s pulse lasts (game ticks)', fact('observerPulseGameTicks').value, b.lasting(() => obs.output === 15) * GT, { fact: 'observerPulseGameTicks' });
  }
  { // Buttons: stone 20 game ticks, wooden 30.
    const [stoneTicks, woodTicks] = fact('buttonGameTicks').value;
    for (const [name, id, want] of [['Stone Button', BLOCKS.STONE_BUTTON, stoneTicks], ['Polished Blackstone Button', cellForName('Polished Blackstone Button')?.id, stoneTicks], ['Oak Button', cellForName('Oak Button')?.id, woodTicks], ['Crimson Button', cellForName('Crimson Button')?.id, woodTicks]]) {
      const b = redstoneBench(); const s = b.put(0, 1, 0, id);
      if (!s) { add('R-BUTTON', name, `A ${name} stays on (game ticks)`, want, 'not a redstone component', { fact: 'buttonGameTicks' }); continue; }
      b.rs.interact([0, 1, 0]);
      add('R-BUTTON', name, `A ${name} stays on (game ticks)`, want, b.lasting(() => s.output === 15) * GT, { fact: 'buttonGameTicks' });
    }
  }
  { // Pressure plates: who presses them, what they give, how long they hold.
    const [weightedCheck, otherCheck] = fact('plateCheckGameTicks').value;
    const standing = (n, kind = 'mob') => Array.from({ length: n }, () => (kind === 'player' ? { position: { x: 0.5, y: 1, z: 0.5 } } : { type: 'zombie', mesh: { position: { x: 0.5, y: 1, z: 0.5 } } }));
    const plate = (name) => { const b = redstoneBench(); const s = b.put(0, 1, 0, cellForName(name)?.id); return { b, s }; };
    for (const [name, crowd, want] of [['Oak Pressure Plate', 1, 15], ['Stone Pressure Plate', 1, 15], ['Light Weighted Pressure Plate', 3, 3], ['Light Weighted Pressure Plate', 20, fact('lightPlate').value], ['Heavy Weighted Pressure Plate', 11, Math.ceil(11 / fact('heavyPlate').value)]]) {
      const { b, s } = plate(name);
      if (!s) { add('R-PLATE', name, `${crowd} mob(s) on a ${name}`, want, 'not a redstone component', { fact: /Heavy/.test(name) ? 'heavyPlate' : 'lightPlate' }); continue; }
      b.tick(2, standing(crowd));
      add('R-PLATE', name, `${crowd} mob(s) on a ${name} give`, want, s.output, { fact: /Heavy/.test(name) ? 'heavyPlate' : 'lightPlate' });
    }
    for (const [name, want] of [['Oak Pressure Plate', otherCheck], ['Light Weighted Pressure Plate', weightedCheck]]) {
      const { b, s } = plate(name); b.tick(2, standing(1, 'player'));
      add('R-PLATE', name, `A ${name} stays pressed after the player steps off (game ticks)`, want, b.holdsAfter(() => s.output > 0) * GT, { fact: 'plateCheckGameTicks' });
    }
  }
  { // Dropper: fires 4 game ticks after it is powered.
    const b = redstoneBench(); const d = b.put(0, 1, 0, BLOCKS.DROPPER, 0); d.inventory.push({ id: 'stick', isBlock: false, count: 1 });
    let firedAt = null; b.rs.dispense = () => { firedAt = b.rs.tickNumber; };
    const lever = b.put(0, 1, 1, BLOCKS.LEVER); b.tick(2); lever.on = true; const start = b.rs.tickNumber + 1; b.tick(6);
    add('R-DROPPER', 'dropper', 'A dropper ejects after being powered (game ticks)', fact('dropperDelayGameTicks').value, firedAt === null ? 'never' : (firedAt - start) * GT, { fact: 'dropperDelayGameTicks' });
  }
  { // Hopper: one item per 8 game ticks.
    const b = redstoneBench(); const h = b.put(0, 1, 0, BLOCKS.HOPPER, 0); h.inventory.push({ id: 'stick', isBlock: false, count: 10 });
    b.put(1, 1, 0, BLOCKS.HOPPER, 0);
    const moved = []; let last = 10;
    for (let i = 0; i < 24; i++) { b.tick(); const left = h.inventory[0]?.count ?? 0; if (left < last) moved.push(b.rs.tickNumber); last = left; }
    const gap = moved.length > 1 ? (moved[1] - moved[0]) * GT : 'no transfers';
    add('R-HOPPER', 'hopper', 'A hopper moves an item every (game ticks)', fact('hopperCooldownGameTicks').value, gap, { fact: 'hopperCooldownGameTicks' });
  }
  { // Note block: 25 pitches, then round to the first.
    const b = redstoneBench(); const n = b.put(0, 1, 0, BLOCKS.NOTE_BLOCK); b.rs.playNote = () => {};
    const notes = new Set([n.note || 0]); for (let i = 0; i < 25; i++) { b.rs.interact([0, 1, 0]); notes.add(n.note); }
    add('R-NOTE', 'note_block', 'A note block has this many pitches', fact('noteBlockPitches').value, notes.size, { fact: 'noteBlockPitches' });
  }
  { // Target block: arrows hold 20 game ticks, other projectiles 8; a bull's-eye gives 15.
    const [other, arrow] = fact('targetGameTicks').value;
    for (const [projectile, want] of [['arrow', arrow], ['snowball', other]]) {
      const b = redstoneBench(); const t = b.put(0, 1, 0, BLOCKS.TARGET_BLOCK); b.tick(2);
      b.rs.hitTarget([0, 1, 0], { x: 0.5, y: 1.5, z: 0.5 }, projectile);
      if (projectile === 'arrow') add('R-TARGET', 'target', 'A hit in the centre of a target gives', 15, t.output, { fact: 'targetGameTicks' });
      add('R-TARGET', 'target', `A target hit by a ${projectile} stays on (game ticks)`, want, b.lasting(() => t.output > 0) * GT, { fact: 'targetGameTicks' });
    }
  }
  { // Lightning rod: 15 for 8 game ticks.
    const b = redstoneBench(); const rod = b.put(0, 1, 0, BLOCKS.LIGHTNING_ROD); b.tick(2); b.rs.strikeRod([0, 1, 0]);
    add('R-ROD', 'lightning_rod', 'A struck lightning rod gives 15 for (game ticks)', fact('lightningRodGameTicks').value, b.lasting(() => rod.output === 15) * GT, { fact: 'lightningRodGameTicks' });
  }
  { // Comparator reading a container: the page's own example, 300 items in a 9-slot container -> 8; ender pearls by 16s.
    const b = redstoneBench(); const d = b.put(0, 1, 0, BLOCKS.DROPPER);
    for (let i = 0; i < 4; i++) d.inventory.push({ id: 'cobblestone', isBlock: false, count: 64 }); d.inventory.push({ id: 'cobblestone', isBlock: false, count: 44 });
    add('R-CONTAINER', 'comparator', 'A 9-slot container holding 300 items reads', 8, b.rs.getContainerSignal([0, 1, 0]), { fact: 'containerFormula' });
    const e = redstoneBench(); const d2 = e.put(0, 1, 0, BLOCKS.DROPPER); d2.inventory.push({ id: 'ender_pearl', isBlock: false, count: 16 });
    add('R-CONTAINER', 'comparator', 'A 9-slot container holding a full stack of 16 ender pearls reads', Math.floor(1 + (1 / 9) * 14), e.rs.getContainerSignal([0, 1, 0]), { fact: 'containerFormula' });
  }
  return out;
}

// --- everything ---------------------------------------------------------------------------------------------------

export function systemsAudit() {
  const rows = [...tradeCases(), ...brewingCases(), ...enchantingCases(), ...effectCases(), ...smithingCases(), ...commandCases(), ...redstoneCases()];
  const totals = { PASS: 0, FAIL: 0, KNOWN: 0, NA: 0 };
  const byCase = {};
  for (const r of rows) { totals[r.status]++; byCase[r.id] ??= { PASS: 0, FAIL: 0, KNOWN: 0, NA: 0 }; byCase[r.id][r.status]++; }
  return { rows, totals, byCase, failures: rows.filter((r) => r.status === 'FAIL') };
}
